package sn.ucad.nexora.espace.application.service;
import java.time.LocalDateTime; import java.util.UUID; import org.springframework.stereotype.Service; import sn.ucad.nexora.espace.application.dto.request.CreateEspaceRequest; import sn.ucad.nexora.espace.application.usecase.CreateEspaceUseCase; import sn.ucad.nexora.espace.domain.entity.EspaceProfessionnel; import sn.ucad.nexora.espace.domain.repository.EspaceRepository; import sn.ucad.nexora.espace.infrastructure.persistence.UtilisateurLookupRepository;
@Service public class CreateEspaceService implements CreateEspaceUseCase{
 private final EspaceRepository espaceRepository; private final UtilisateurLookupRepository utilisateurRepository;
 public CreateEspaceService(EspaceRepository e,UtilisateurLookupRepository u){this.espaceRepository=e;this.utilisateurRepository=u;}
 public EspaceProfessionnel create(UUID accountId,CreateEspaceRequest r){if(accountId==null)throw new IllegalArgumentException("Compte authentifié obligatoire");Long uid=utilisateurRepository.findIdByAccountId(accountId).orElseThrow(()->new IllegalArgumentException("Profil utilisateur introuvable"));EspaceProfessionnel e=new EspaceProfessionnel();e.setUtilisateurId(uid);e.setTypeEspaceId(r.getTypeEspaceId());e.setNom(r.getNom().trim());e.setSlogan(r.getSlogan());e.setDescription(r.getDescription());e.setTelephone(r.getTelephone());e.setTelephoneSecondaire(r.getTelephoneSecondaire());e.setEmail(r.getEmail());e.setSiteWeb(r.getSiteWeb());e.setRegistreCommerce(r.getRegistreCommerce());e.setNumeroNinea(r.getNumeroNinea());e.setNumeroRccm(r.getNumeroRccm());e.setOuvert(true);e.setStatut("ACTIF");e.setCertifie(false);e.setVerifie(false);e.setDateCreation(LocalDateTime.now());e.setDateModification(LocalDateTime.now());return espaceRepository.save(e);}
}
